package rustanything;

import java.lang.reflect.Array;
import java.lang.reflect.GenericArrayType;
import java.lang.reflect.ParameterizedType;
import java.lang.reflect.Type;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/** Generated by rust-anything: a dependency-free JSON codec for the bridge. */
public final class RustAnythingJson {
    private RustAnythingJson() {}

    /** Captures a generic type: {@code new TypeRef<List<String>>() {}.type()}. */
    public abstract static class TypeRef<T> {
        public Type type() {
            return ((ParameterizedType) getClass().getGenericSuperclass()).getActualTypeArguments()[0];
        }
    }

    /** A value that does not fit the declared type. */
    public static final class Mismatch extends RuntimeException {
        public Mismatch(String message) {
            super(message);
        }
    }

    // ---- parse ----

    public static Object parse(String text) {
        int[] pos = {0};
        Object value = value(text, pos);
        skip(text, pos);
        if (pos[0] != text.length()) {
            throw new IllegalArgumentException("trailing JSON at " + pos[0]);
        }
        return value;
    }

    private static void skip(String s, int[] pos) {
        while (pos[0] < s.length() && Character.isWhitespace(s.charAt(pos[0]))) {
            pos[0]++;
        }
    }

    private static Object value(String s, int[] pos) {
        skip(s, pos);
        char c = s.charAt(pos[0]);
        if (c == '{') {
            Map<String, Object> map = new LinkedHashMap<>();
            pos[0]++;
            skip(s, pos);
            if (s.charAt(pos[0]) == '}') {
                pos[0]++;
                return map;
            }
            while (true) {
                skip(s, pos);
                String key = string(s, pos);
                skip(s, pos);
                pos[0]++; // ':'
                map.put(key, value(s, pos));
                skip(s, pos);
                if (s.charAt(pos[0]++) == '}') {
                    return map;
                }
            }
        }
        if (c == '[') {
            List<Object> list = new ArrayList<>();
            pos[0]++;
            skip(s, pos);
            if (s.charAt(pos[0]) == ']') {
                pos[0]++;
                return list;
            }
            while (true) {
                list.add(value(s, pos));
                skip(s, pos);
                if (s.charAt(pos[0]++) == ']') {
                    return list;
                }
            }
        }
        if (c == '"') {
            return string(s, pos);
        }
        if (s.startsWith("true", pos[0])) {
            pos[0] += 4;
            return Boolean.TRUE;
        }
        if (s.startsWith("false", pos[0])) {
            pos[0] += 5;
            return Boolean.FALSE;
        }
        if (s.startsWith("null", pos[0])) {
            pos[0] += 4;
            return null;
        }
        int start = pos[0];
        while (pos[0] < s.length() && "+-0123456789.eE".indexOf(s.charAt(pos[0])) >= 0) {
            pos[0]++;
        }
        String number = s.substring(start, pos[0]);
        if (number.contains(".") || number.contains("e") || number.contains("E")) {
            return Double.parseDouble(number);
        }
        BigInteger big = new BigInteger(number);
        return big.bitLength() < 64 ? (Object) big.longValue() : big;
    }

    private static String string(String s, int[] pos) {
        StringBuilder out = new StringBuilder();
        pos[0]++; // opening quote
        while (true) {
            char c = s.charAt(pos[0]++);
            if (c == '"') {
                return out.toString();
            }
            if (c != '\\') {
                out.append(c);
                continue;
            }
            char e = s.charAt(pos[0]++);
            switch (e) {
                case 'n': out.append('\n'); break;
                case 't': out.append('\t'); break;
                case 'r': out.append('\r'); break;
                case 'b': out.append('\b'); break;
                case 'f': out.append('\f'); break;
                case 'u':
                    out.append((char) Integer.parseInt(s.substring(pos[0], pos[0] + 4), 16));
                    pos[0] += 4;
                    break;
                default: out.append(e);
            }
        }
    }

    // ---- write ----

    /** JSON text of a Java value; floats JSON cannot carry become {"$num": ...}. */
    public static String write(Object v) {
        StringBuilder out = new StringBuilder();
        write(out, v);
        return out.toString();
    }

    private static void write(StringBuilder out, Object v) {
        if (v == null) {
            out.append("null");
        } else if (v instanceof String || v instanceof Character) {
            quote(out, v.toString());
        } else if (v instanceof Double || v instanceof Float) {
            double d = ((Number) v).doubleValue();
            if (Double.isNaN(d)) {
                out.append("{\"$num\":\"NaN\"}");
            } else if (Double.isInfinite(d)) {
                out.append(d > 0 ? "{\"$num\":\"Infinity\"}" : "{\"$num\":\"-Infinity\"}");
            } else if (d == 0 && 1 / d < 0) {
                out.append("{\"$num\":\"-0\"}");
            } else if (d == Math.rint(d) && Math.abs(d) < 1e16) {
                out.append(Long.toString((long) d)).append(".0");
            } else {
                out.append(Double.toString(d).replace("E", "e"));
            }
        } else if (v instanceof Number || v instanceof Boolean) {
            out.append(v.toString());
        } else if (v instanceof Optional) {
            write(out, ((Optional<?>) v).orElse(null));
        } else if (v instanceof Map) {
            out.append('{');
            boolean first = true;
            for (Map.Entry<?, ?> e : ((Map<?, ?>) v).entrySet()) {
                if (!first) {
                    out.append(',');
                }
                first = false;
                quote(out, String.valueOf(e.getKey()));
                out.append(':');
                write(out, e.getValue());
            }
            out.append('}');
        } else if (v instanceof Collection) {
            out.append('[');
            boolean first = true;
            for (Object x : (Collection<?>) v) {
                if (!first) {
                    out.append(',');
                }
                first = false;
                write(out, x);
            }
            out.append(']');
        } else if (v.getClass().isArray()) {
            List<Object> items = new ArrayList<>();
            for (int i = 0; i < Array.getLength(v); i++) {
                items.add(Array.get(v, i));
            }
            write(out, items);
        } else {
            out.append("{\"$object\":");
            quote(out, v.getClass().getName());
            out.append('}');
        }
    }

    private static void quote(StringBuilder out, String s) {
        out.append('"');
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            switch (c) {
                case '"': out.append("\\\""); break;
                case '\\': out.append("\\\\"); break;
                case '\n': out.append("\\n"); break;
                case '\t': out.append("\\t"); break;
                case '\r': out.append("\\r"); break;
                default:
                    if (c < 0x20 || Character.isSurrogate(c)) {
                        // Escaped surrogates keep lone halves intact through any UTF-8 layer.
                        out.append(String.format("\\u%04x", (int) c));
                    } else {
                        out.append(c);
                    }
            }
        }
        out.append('"');
    }

    // ---- convert ----

    private static double number(Object v) {
        if (v instanceof Number) {
            return ((Number) v).doubleValue();
        }
        if (v instanceof Map && ((Map<?, ?>) v).containsKey("$num")) {
            switch (String.valueOf(((Map<?, ?>) v).get("$num"))) {
                case "NaN": return Double.NaN;
                case "Infinity": return Double.POSITIVE_INFINITY;
                case "-Infinity": return Double.NEGATIVE_INFINITY;
                case "-0": return -0.0;
                default: break;
            }
        }
        throw new Mismatch("not a number: " + v);
    }

    private static long integer(Object v, long min, long max) {
        if (v instanceof Long || v instanceof Integer) {
            long n = ((Number) v).longValue();
            if (n >= min && n <= max) {
                return n;
            }
        }
        throw new Mismatch("not an integer in range: " + v);
    }

    /** Converts a parsed JSON value to {@code type}. */
    public static Object convert(Object v, Type type) {
        if (type instanceof ParameterizedType) {
            ParameterizedType p = (ParameterizedType) type;
            Class<?> raw = (Class<?>) p.getRawType();
            Type[] args = p.getActualTypeArguments();
            if (Optional.class.equals(raw)) {
                return v == null ? Optional.empty() : Optional.of(convert(v, args[0]));
            }
            if (v == null) {
                return null;
            }
            if (Map.class.isAssignableFrom(raw)) {
                if (!(v instanceof Map)) {
                    throw new Mismatch("not an object");
                }
                Map<String, Object> out = new LinkedHashMap<>();
                for (Map.Entry<?, ?> e : ((Map<?, ?>) v).entrySet()) {
                    out.put((String) e.getKey(), convert(e.getValue(), args[1]));
                }
                return out;
            }
            if (Iterable.class.isAssignableFrom(raw)) {
                if (!(v instanceof List)) {
                    throw new Mismatch("not an array");
                }
                List<Object> out = new ArrayList<>();
                for (Object x : (List<?>) v) {
                    out.add(convert(x, args[0]));
                }
                return out;
            }
            throw new Mismatch("unsupported type " + type);
        }
        if (type instanceof GenericArrayType) {
            return array(v, ((GenericArrayType) type).getGenericComponentType());
        }
        Class<?> c = (Class<?>) type;
        if (c.isArray()) {
            return array(v, c.getComponentType());
        }
        if (v == null) {
            if (c.isPrimitive()) {
                throw new Mismatch("null for " + c);
            }
            return null;
        }
        if (c == String.class || c == CharSequence.class) {
            if (!(v instanceof String)) {
                throw new Mismatch("not a string");
            }
            return v;
        }
        if (c == int.class || c == Integer.class) {
            return (int) integer(v, Integer.MIN_VALUE, Integer.MAX_VALUE);
        }
        if (c == long.class || c == Long.class) {
            return integer(v, Long.MIN_VALUE, Long.MAX_VALUE);
        }
        if (c == short.class || c == Short.class) {
            return (short) integer(v, Short.MIN_VALUE, Short.MAX_VALUE);
        }
        if (c == byte.class || c == Byte.class) {
            return (byte) integer(v, Byte.MIN_VALUE, Byte.MAX_VALUE);
        }
        if (c == double.class || c == Double.class) {
            return number(v);
        }
        if (c == float.class || c == Float.class) {
            return (float) number(v);
        }
        if (c == boolean.class || c == Boolean.class) {
            if (!(v instanceof Boolean)) {
                throw new Mismatch("not a boolean");
            }
            return v;
        }
        if (c == Object.class) {
            return v;
        }
        throw new Mismatch("unsupported type " + c);
    }

    private static Object array(Object v, Type component) {
        if (!(v instanceof List)) {
            throw new Mismatch("not an array");
        }
        List<?> list = (List<?>) v;
        Class<?> raw = component instanceof Class ? (Class<?>) component : (Class<?>) ((ParameterizedType) component).getRawType();
        Object out = Array.newInstance(raw, list.size());
        for (int i = 0; i < list.size(); i++) {
            Array.set(out, i, convert(list.get(i), component));
        }
        return out;
    }
}
